'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const t = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--)
    t[i][j] = a[i] === b[j] ? t[i + 1][j + 1] + 1 : Math.max(t[i + 1][j], t[i][j + 1]);
  return t[0][0];
}
let seed = 12345;
const rnd = (n) => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) % n);
const alpha = ['', 'x', 'y', '-x', '+y', ' z', '__proto__'];
const gen = (n, k) => Array.from({ length: n }, () => alpha[rnd(k)]);

for (let iter = 0; iter < 20000; iter++) {
  const k = 1 + rnd(alpha.length);
  const a = gen(rnd(14), k), b = gen(rnd(14), k);
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const ed = s.filter((e) => e.op !== 'equal').length;
  assert.equal(ed, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3, 5]) {
    const h = unifiedHunks(a, b, { context });
    if (ed === 0) assert.deepEqual(h, []);
    assert.deepEqual(applyHunks(a, h), b);
    assert.deepEqual(a, ac);
    for (const x of h) {
      const t = x.lines.slice().reverse();
      for (let i = 0; i < t.length && t[i][0] === ' '; i++) assert.ok(i < context);
    }
    for (let i = 1; i < h.length; i++) {
      const prevEnd = h[i - 1].oldStart - (h[i - 1].oldLines ? 1 : 0) + h[i - 1].oldLines;
      const start = h[i].oldStart - (h[i].oldLines ? 1 : 0);
      assert.ok(start - prevEnd > 0, 'hunks should not touch');
    }
    if (h.length) {
      const bad = structuredClone(h);
      bad[bad.length - 1].newStart += 1;
      assert.throws(() => applyHunks(a, bad), new RegExp(`hunk ${bad.length - 1} does not apply`));
    }
  }
}
assert.deepEqual(unifiedHunks(['a'], ['x', 'a'], { context: 0 }), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] }]);
assert.deepEqual(unifiedHunks(['x', 'a'], ['a'], { context: 0 }), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] }]);
assert.deepEqual(applyHunks(['a'], []), ['a']);

const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 7 === 0 ? 'same' : i}`);
const big2 = big.slice(); big2[10] = 'chg'; big2.splice(9000, 3); big2.splice(15000, 0, 'new', 'same'); big2[19990] = 'z';
let t0 = performance.now();
const hs = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hs), big2);
diffLines(big, big.slice());
const rep = Array(20000).fill('same'), rep2 = rep.slice(); rep2.splice(5000, 2); rep2.splice(12000, 0, 'q');
assert.equal(diffLines(rep, rep2).filter((e) => e.op !== 'equal').length, 3);
console.log('perf ms', (performance.now() - t0).toFixed(1));
console.log('ok');

